INSERT INTO knowledge_articles (id,type,title,system_id,module_id,category_id,carrier_id,error_code,severity,error_message,description,root_cause,resolution,sop_steps,validation_steps,escalation_path,keywords,status,owner_id,created_by,updated_by,is_sample,view_count,created_at,updated_at) VALUES
(1,'Error','UPS Missing/Invalid PostalCode of payment account',1,1,1,1,'UPS-ADDR-104','High','Missing or invalid PostalCode of payment account','UPS rejects the shipment because the payment account address does not contain a valid postal code.','The shipper or third-party billing account profile has an empty, malformed, or country-mismatched postal code.','Open carrier account configuration, verify the billing address country and postal code, save the account, then retry the shipment.','1. Open Settings > Carrier Accounts > UPS.\n2. Select the payment account used by the order.\n3. Confirm country and PostalCode match the UPS account profile.\n4. Save and re-rate the shipment.\n5. Generate the label again.','A successful rate response and label confirm the correction.','Escalate to Carrier Integrations with account alias and correlation ID after two failed retries.','UPS postal code payment account label address','Published',1,1,1,1,148,NOW()-INTERVAL 1 DAY,NOW()-INTERVAL 1 DAY),
(2,'SOP','USPS ExtraServices not valid at APO/FPO/DPO/FAS',1,1,2,2,'USPS-APO-220','Medium','ExtraServices are not valid for the destination address','A military mail label fails when an unsupported USPS extra service is selected.','APO, FPO, DPO, and FAS destinations accept a limited set of extra services.','Remove the unsupported option and select a service supported for the destination and mail class.','1. Confirm the city is APO, FPO, DPO, or FAS.\n2. Review selected ExtraServices.\n3. Remove Signature Confirmation or other unsupported service.\n4. Retain only services allowed by the USPS military mail matrix.\n5. Recreate the label.','The USPS response returns a label without an ExtraServices validation error.','Escalate with sanitized request/response payloads if supported services still fail.','USPS APO FPO DPO military extra services','Published',1,1,1,1,135,NOW()-INTERVAL 2 DAY,NOW()-INTERVAL 2 DAY),
(3,'Error','DHL Product Finding Failed',1,2,3,3,'DHL-PRODUCT-404','High','Product finding failed','DHL cannot select an eligible product for the shipment route and package.','Origin, destination, weight, dimensions, or account capabilities do not match an enabled DHL product.','Validate route and parcel data, then confirm the account is enabled for the requested DHL product.','1. Confirm origin and destination country codes.\n2. Verify weight and dimensions are positive and within product limits.\n3. Check DHL account product entitlements.\n4. Remove a forced service code and retry product discovery.','At least one eligible DHL service appears in the rate response.','Escalate to DHL support with timestamp, account alias, and request ID.','DHL product finding service route dimensions','Published',1,1,1,1,122,NOW()-INTERVAL 3 DAY,NOW()-INTERVAL 3 DAY),
(4,'Error','DHL Data Validation Failed',1,1,2,3,'DHL-VALIDATION-400','Medium','Data validation failed','DHL rejected one or more shipment data fields before rating or label creation.','A required address, customs, contact, or package field is missing or in an invalid format.','Correct the field identified in the DHL validation detail and resubmit.','1. Open the carrier response detail.\n2. Identify the field path in the validation message.\n3. Correct the source order or shipment.\n4. Confirm customs data for international shipments.\n5. Retry once.','The request passes validation and returns rates or a label.','Send the redacted payload and correlation ID to Carrier Integrations if no field is identified.','DHL validation customs address API','Published',1,1,1,1,109,NOW()-INTERVAL 4 DAY,NOW()-INTERVAL 4 DAY),
(5,'Error','WMS Order failed to import',2,3,4,5,'WMS-IMPORT-001','Critical','Order failed to import','An order is present upstream but is not available for warehouse allocation.','Required customer, SKU, facility, or address mapping is missing, or the import message is malformed.','Correct the source data or mapping and replay the message from the integration queue.','1. Locate the order in Integration Monitor.\n2. Review the first blocking validation message.\n3. Correct master data or the source order.\n4. Replay the message once.\n5. Confirm the order reaches Ready status.','The order appears in WMS with expected lines, facility, and Ready status.','Escalate to WMS L2 with order number, queue message ID, and validation output.','WMS order import SKU mapping queue','Published',1,1,1,1,96,NOW()-INTERVAL 5 DAY,NOW()-INTERVAL 5 DAY),
(6,'SOP','FMS Load not showing',3,4,5,5,'FMS-LOAD-012','High','Load is not visible in FMS','A planned or tendered load is not visible to the expected operations team.','The load may be filtered, assigned to another business unit, delayed in integration, or missing required routing data.','Check filters and ownership, verify the outbound integration event, then replay only if the event failed.','1. Clear FMS date and status filters.\n2. Search by exact load and shipment numbers.\n3. Verify business unit and user access.\n4. Check the WMS outbound event status.\n5. Replay a failed event once and refresh FMS.','The load is visible with the expected stops and ownership.','Escalate to FMS L2 with load number, business unit, and event ID.','FMS load visibility filters integration','Published',1,1,1,1,83,NOW()-INTERVAL 6 DAY,NOW()-INTERVAL 6 DAY),
(7,'Error','Carrier Failed to retrieve UPS-MI-Rate',1,2,6,4,'UPS-MI-RATE-503','High','Failed to retrieve UPS-MI-Rate','Rate shopping returns no UPS Mail Innovations price for an otherwise valid parcel.','Account credentials, service eligibility, package constraints, or a temporary carrier gateway issue blocked the quote.','Validate account status and parcel eligibility, then retry after checking carrier gateway health.','1. Check Carrier Gateway status.\n2. Confirm UPS-MI credentials are active.\n3. Validate destination, weight, and package type.\n4. Remove forced service selections.\n5. Retry the rate request once.','A UPS-MI service and price are returned.','Escalate with correlation ID and sanitized rate request after confirming gateway health.','UPS MI rate retrieval credentials carrier','Published',1,1,1,1,70,NOW()-INTERVAL 7 DAY,NOW()-INTERVAL 7 DAY),
(8,'Article','How to request API access',5,5,8,5,'REQ-API-ACCESS','Low',NULL,'Standard process for requesting non-production or production API access.','Access is provisioned only after owner approval and security review.','Submit an access request with environment, business purpose, owner, and expiration date.','1. Open the service request portal.\n2. Select Integration API Access.\n3. Provide environment and business justification.\n4. Add the approving system owner.\n5. Never include secrets in the request.','The approved identity can authenticate with least-privilege scopes.','Contact Identity Operations for approved requests that exceed the stated SLA.','API access request configuration credentials','Published',1,1,1,1,57,NOW()-INTERVAL 8 DAY,NOW()-INTERVAL 8 DAY);
